    /** Whether an icon of this name exists. Accepts "search" or "bi-search". */
    public static function ada(string $nama): bool
    {
        return isset(self::JALUR[self::normal($nama)]);
    }

    /**
     * One icon as an <svg> element sized to the surrounding text (1em) and
     * inheriting its colour, so it drops in wherever the old <i class="bi"> was.
     *
     * An unknown name renders nothing rather than a broken glyph — a missing
     * decoration must never take a page down.
     */
    public static function svg(string $nama, string $kelas = ''): string
    {
        $jalur = self::JALUR[self::normal($nama)] ?? null;

        if ($jalur === null) {
            return '';
        }

        $atribut = $kelas === '' ? '' : ' class="'.e($kelas).'"';

        return '<svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 16 16"'
            .' fill="currentColor" aria-hidden="true" focusable="false"'
            .' style="vertical-align:-.125em;flex:none"'.$atribut.'>'.$jalur.'</svg>';
    }

    /** Names carry a "bi-" prefix in older markup and in stored values. */
    private static function normal(string $nama): string
    {
        return str_starts_with($nama, 'bi-') ? substr($nama, 3) : $nama;
    }
}
